import{_ as o,a0 as a,w as d,s as p,I as l,x as e,a1 as u,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Ubuntu 中如何安裝或升級 Linux 內核到4.2 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中如何安裝或升級 Linux 內核到4.2 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中如何安裝或升級 Linux 內核到4.2 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中如何安裝或升級 Linux 內核到4.2 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu","title":"在 Ubuntu 中如何安裝或升級 Linux 內核到4.2","tag":"201509","desc":""},"relativePath":"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu.md","filePath":"[post].md"}'),x={name:"201509/20150901 How to Install or Upgrade to Linux Kernel 4.2 in Ubuntu.md"};function s(b,n,m,g,k,_){const t=a("Link");return d(),p("div",null,[n[20]||(n[20]=l("h1",{id:"在-ubuntu-中如何安裝或升級-linux-內核到4-2",tabindex:"-1"},[e("在 Ubuntu 中如何安裝或升級 Linux 內核到4.2 "),l("a",{class:"header-anchor",href:"#在-ubuntu-中如何安裝或升級-linux-內核到4-2","aria-label":"Permalink to “在 Ubuntu 中如何安裝或升級 Linux 內核到4.2”"},"​")],-1)),n[21]||(n[21]=l("p",null,[l("img",{src:"http://ubuntuhandbook.org/wp-content/uploads/2014/12/linux-kernel-icon-tux.png",alt:""})],-1)),l("p",null,[n[1]||(n[1]=e("Linux 內核 4.2已經發布了。Linus Torvalds 在 ",-1)),u(t,{href:"https://lkml.org/lkml/2015/8/30/96"},{default:i(()=>[...n[0]||(n[0]=[e("lkml.org",-1)])]),_:1}),n[2]||(n[2]=e(" 上寫到:",-1))]),n[22]||(n[22]=r('<blockquote><p>通過這周這麼小的變動，看來在最後一週 發佈 4.2 版本應該不會有問題，當然還有幾個修正，但是看起來也並不需要延遲一週。 所以這就到了，而且 4.3 的合併窗口現已打開。我已經有了幾個等待處理的合併請求，明天我開始處理它們，然後在適當的時候放出來。 從 rc8 以來的簡短日誌很小，已經附加。這個補丁也很小...</p></blockquote><h3 id="新內核-4-2-有哪些改進" tabindex="-1">新內核 4.2 有哪些改進？: <a class="header-anchor" href="#新內核-4-2-有哪些改進" aria-label="Permalink to “新內核 4.2 有哪些改進？:”">​</a></h3><ul><li>重寫英特爾的x86彙編代碼</li><li>支持新的 ARM 板和 SoC</li><li>對 F2FS 的 per-file 加密</li><li>AMDGPU 的內核 DRM 驅動程序</li><li>對 Radeon DRM 驅動的 VCE1 視頻編碼支持</li><li>初步支持英特爾的 Broxton Atom SoC</li><li>支持 ARCv2 和 HS38 CPU 內核</li><li>增加了隊列自旋鎖的支持</li><li>許多其他的改進和驅動更新。</li></ul><h3 id="在-ubuntu-中如何下載4-2內核" tabindex="-1">在 Ubuntu 中如何下載4.2內核 : <a class="header-anchor" href="#在-ubuntu-中如何下載4-2內核" aria-label="Permalink to “在 Ubuntu 中如何下載4.2內核 :”">​</a></h3><p>此內核版本的二進制包可供下載鏈接如下：</p>',5)),l("ul",null,[l("li",null,[u(t,{href:"https://lkml.org/lkml/2015/8/30/96"},{default:i(()=>[...n[3]||(n[3]=[e("下載 4.2 內核(.DEB)",-1)])]),_:1})])]),n[23]||(n[23]=r(`<p>首先檢查你的操作系統類型，32位（i386）的或64位(amd64)的，然後使用下面的方式依次下載並安裝軟件包：</p><ol><li>linux-headers-4.2.0-xxx_all.deb</li><li>linux-headers-4.2.0-xxx-generic_xxx_i386/amd64.deb</li><li>linux-image-4.2.0-xxx-generic_xxx_i386/amd64.deb</li></ol><p>安裝內核後，在終端（(Ctrl+Alt+T)）運行<code>sudo update-grub</code>命令來更新 grub boot-loader。</p><p>如果你需要一個低延遲系統（例如用於錄製音頻），請下載並安裝下面的包：</p><ol><li>linux-headers-4.2.0_xxx_all.deb</li><li>linux-headers-4.2.0-xxx-lowlatency_xxx_i386/amd64.deb</li><li>linux-image-4.2.0-xxx-lowlatency_xxx_i386/amd64.deb</li></ol><p>對於沒有圖形用户界面的 Ubuntu 服務器，你可以運行下面的命令通過 wget 來逐一抓下載，並通過 dpkg 來安裝：</p><p>對於64位的系統請運行:</p><pre><code>cd /tmp/

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200_4.2.0-040200.201508301530_all.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200-generic_4.2.0-040200.201508301530_amd64.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-image-4.2.0-040200-generic_4.2.0-040200.201508301530_amd64.deb

sudo dpkg -i linux-headers-4.2.0-*.deb linux-image-4.2.0-*.deb
</code></pre><p>對於32位的系統,請運行:</p><pre><code>cd /tmp/

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200_4.2.0-040200.201508301530_all.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-headers-4.2.0-040200-generic_4.2.0-040200.201508301530_i386.deb

wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v4.2-unstable/linux-image-4.2.0-040200-generic_4.2.0-040200.201508301530_i386.deb

sudo dpkg -i linux-headers-4.2.0-*.deb linux-image-4.2.0-*.deb
</code></pre><p>最後，重新啓動計算機才能生效。</p>`,11)),l("p",null,[n[5]||(n[5]=e("要恢復或刪除舊的內核，請參閲",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/2015/08/install-latest-kernel-script/"},{default:i(()=>[...n[4]||(n[4]=[e("通過腳本安裝內核",-1)])]),_:1}),n[6]||(n[6]=e("。",-1))]),n[24]||(n[24]=l("hr",null,null,-1)),l("p",null,[n[8]||(n[8]=e("via: ",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/2015/08/upgrade-kernel-4-2-ubuntu/"},{default:i(()=>[...n[7]||(n[7]=[e("http://ubuntuhandbook.org/index.php/2015/08/upgrade-kernel-4-2-ubuntu/",-1)])]),_:1})]),l("p",null,[n[12]||(n[12]=e("作者：",-1)),u(t,{href:"http://ubuntuhandbook.org/index.php/about/"},{default:i(()=>[...n[9]||(n[9]=[e("Ji m",-1)])]),_:1}),n[13]||(n[13]=e(" 譯者：",-1)),u(t,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...n[10]||(n[10]=[e("strugglingyouth",-1)])]),_:1}),n[14]||(n[14]=e(" 校對：",-1)),u(t,{href:"https://github.com/wxy"},{default:i(()=>[...n[11]||(n[11]=[e("wxy",-1)])]),_:1})]),l("p",null,[n[17]||(n[17]=e("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[15]||(n[15]=[e("LCTT",-1)])]),_:1}),n[18]||(n[18]=e(" 原創編譯，",-1)),u(t,{href:"https://linux.cn/"},{default:i(()=>[...n[16]||(n[16]=[e("Linux中國",-1)])]),_:1}),n[19]||(n[19]=e(" 榮譽推出",-1))])])}const L=o(x,[["render",s]]);export{C as __pageData,L as default};
